/**
 * Every active member of the org with their user record, unpaged — mention
 * resolution must see the whole roster, however large the org.
 */
export async function listActiveMembersWithUsers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const rows = getDb()
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        ...compact(
          orgPredicate(members.orgId, orgId),
          liveMemberPredicate(),
          eq(members.status, "active"),
        ),
      ),
    )
    .orderBy(asc(members.createdAt), asc(members.id))
    .all();

  return rows.map((row) => ({ ...toMember(row.member), user: toUser(row.user) }));
}

/** The seat count every plan check compares against. */

