import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

it("scenario", async () => {
  const t = await createTenant("scratch");
  const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "x", assigneeId: t.userIds.admin } as never));
  const a = await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "hi @admin @viewer @owner", parentId: null, mentionedUserIds: [] });
  expect(new Set(a.mentionedUserIds)).toEqual(new Set([t.userIds.admin, t.userIds.viewer]));
  const b = await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: issue.id, body: "reply", parentId: a.id, mentionedUserIds: [] });
  const c = await commentService.createComment(t.actors.admin, { orgId: t.org.id, issueId: issue.id, body: "reply2", parentId: b.id, mentionedUserIds: [] });
  await commentService.deleteComment(t.actors.owner, { orgId: t.org.id, commentId: a.id });
  const thread = await commentService.getThread(t.actors.owner, t.org.id, issue.id);
  expect(thread).toHaveLength(1);
  expect(thread[0]!.comment.body).toBe("");
  expect(thread[0]!.replies.map((r) => r.id)).toEqual([b.id, c.id]);
  const edited = await commentService.updateComment(t.actors.admin, { orgId: t.org.id, commentId: c.id, body: "now @member" });
  expect(edited.mentionedUserIds).toEqual([t.userIds.member]);
  const n = await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.member, unreadOnly: false, limit: 25, cursor: null } as never);
  console.log(n.items.map((x) => x.kind));
  const adm = await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.admin, unreadOnly: false, limit: 25, cursor: null } as never);
  console.log(adm.items.map((x) => x.kind));
});
EOF
npx vitest run tests/services/zz-tmp-scratch.test.ts 2>&1 | grep -v "npm warn" | tail -30; rm tests/services/zz-tmp-scratch.test.ts

